"""
Module defining custom exceptions for the qBraid CORE.

"""

from typing import Optional

DEFAULT_ERROR_MESSAGE = (
    "An unexpected error occurred while processing your qBraid command. "
    "Please check your input and try again. If the problem persists, "
    "visit https://github.com/qBraid/community/issues to file a bug report."
)


class QbraidException(Exception):
    """Custom exception class for qBraid core errors."""

    def __init__(self, message: Optional[str] = None):
        if message is None:
            message = DEFAULT_ERROR_MESSAGE
        super().__init__(message)


class HttpStatusMixin:
    """Adds ``status_code`` to exceptions that can carry an HTTP response.

    Mixed into the errors that service clients raise from an ``except
    RequestsApiError`` handler, and *only* those. Errors with no API request
    behind them — configuration, installation, validation — do not get the
    attribute, so its absence is meaningful rather than a permanent ``None``.

    Clients wrap transport failures with ``raise ... from err`` and pass only a
    message, and ``__cause__`` is set *after* ``__init__`` returns, so the status
    cannot be captured at construction. It is read from the chain on access
    instead, which is why no raise site needs to thread it through.
    """

    @property
    def status_code(self) -> Optional[int]:
        """HTTP status of the underlying failed request.

        ``None`` when the request never produced a response — connection error,
        timeout, DNS failure.
        """
        seen: set[int] = set()
        exc: Optional[BaseException] = self  # type: ignore[assignment]
        while exc is not None and id(exc) not in seen:
            seen.add(id(exc))
            # ``_status_code`` is set by RequestsApiError; the ``response`` fallback
            # picks up a raw ``requests`` error still sitting in the chain.
            status = getattr(exc, "_status_code", None)
            if not isinstance(status, int):
                status = getattr(getattr(exc, "response", None), "status_code", None)
            if isinstance(status, int):
                return status
            exc = exc.__cause__
        return None


class QbraidChainedException(Exception):
    """Custom exception class to handle multiple underlying exceptions."""

    def __init__(self, message: Optional[str] = None, exceptions: Optional[list[Exception]] = None):
        if message is None:
            message = "Multiple errors occurred."
        super().__init__(message)
        self.exceptions = exceptions or []

    def add_exception(self, exc: Exception):
        """Add an exception to the chain."""
        self.exceptions.append(exc)


class AuthError(QbraidException):
    """Base class for errors raised authorizing user"""


class ConfigError(QbraidException):
    """Base class for errors raised while setting a user configuartion"""


class RequestsApiError(HttpStatusMixin, QbraidException):
    """Exception re-raising a RequestException.

    ``status_code`` is the HTTP status of the failed response, or ``None`` when
    the request never produced one (connection error, timeout, DNS failure).
    It lets callers distinguish an expected 404 from a real failure without
    parsing the message.
    """

    def __init__(self, message: Optional[str] = None, status_code: Optional[int] = None):
        super().__init__(message)
        # Stored privately because ``HttpStatusMixin.status_code`` is a property,
        # which would otherwise shadow a plain instance attribute.
        self._status_code = status_code


class ResourceNotFoundError(HttpStatusMixin, QbraidException):
    """Exception re-raising a RequestException."""


class UserNotFoundError(ResourceNotFoundError):
    """Exception raised when a user is not found."""
